package federation

import(
	"context"
	"crypto/ed25519"
	"encoding/json"
	"errors"
	"fmt"
	"time"
)

type SchemaRegistry interface{Capability(string)(Capability,bool);Decode(string,string,json.RawMessage)(any,error)}
type AuthorityVerifier interface{VerifyGrant(context.Context,MutationGrant)error;VerifyApproval(context.Context,Intent)error}
type LocalPolicy interface{AuthorizeFederated(context.Context,Intent,MutationGrant,any)error}
type FederatedCommand struct{IntentID ID;Origin Origin;PeerID ID;ActorChain []Actor;TenantID,ResourceKind,ResourceID string;ExpectedGeneration uint64;IdempotencyKey,EffectID string;Risk Risk;Approval *Approval;Payload any}
type LocalResult struct{OperationID,ResultDigest,ErrorCode,ErrorMessage string;Generation uint64;Status IntentStatus;Terminal bool}
type CommandGateway interface{SubmitFederated(context.Context,FederatedCommand)(LocalResult,error);ObserveEffect(context.Context,string)(LocalResult,error)}
type ReceiptSigner interface{ReceiptKeyID(context.Context)(string,error);SignReceipt(context.Context,string,[]byte)([]byte,error)}
type Agent struct{store *Store;schemas SchemaRegistry;authority AuthorityVerifier;policy LocalPolicy;gateway CommandGateway;signer ReceiptSigner;clock func()time.Time}
func NewAgent(store *Store,schemas SchemaRegistry,authority AuthorityVerifier,policy LocalPolicy,gateway CommandGateway,signer ReceiptSigner)(*Agent,error){if store==nil||schemas==nil||authority==nil||policy==nil||gateway==nil||signer==nil{return nil,ErrInvalid};return &Agent{store:store,schemas:schemas,authority:authority,policy:policy,gateway:gateway,signer:signer,clock:time.Now},nil}

func(a *Agent)Accept(ctx context.Context,intent Intent)(Receipt,error){now:=a.clock().UTC();node,epoch,activePeer,err:=a.store.State(ctx);if err!=nil{return Receipt{},err};if err=intent.Validate(now);err!=nil{return a.rejectReceipt(ctx,intent,"INTENT_INVALID",err)};if intent.NodeID!=node||intent.AuthorityEpoch!=epoch||intent.PeerID!=activePeer{return a.rejectReceipt(ctx,intent,"AUTHORITY_STALE",ErrStale)};peer,err:=a.store.Peer(ctx,intent.PeerID);if err!=nil||peer.State!="active"{return a.rejectReceipt(ctx,intent,"PEER_INACTIVE",ErrForbidden)};key,ok:=peer.SigningKeys[intent.SigningKeyID];if !ok||len(key)!=ed25519.PublicKeySize||!ed25519.Verify(ed25519.PublicKey(key),intent.SigStructure(),intent.Signature){return a.rejectReceipt(ctx,intent,"SIGNATURE_INVALID",ErrForbidden)};capability,ok:=a.schemas.Capability(intent.CommandType);if !ok||!capability.RemoteEligible||capability.Version!=intent.ProtocolVersion||capability.SchemaHash!=intent.SchemaHash{return a.rejectReceipt(ctx,intent,"CAPABILITY_UNAVAILABLE",ErrForbidden)};grant,err:=a.store.Grant(ctx,intent.GrantID);if err!=nil{return a.rejectReceipt(ctx,intent,"GRANT_UNAVAILABLE",err)};if err=grant.Validate(now);err!=nil||grant.PeerID!=intent.PeerID||grant.NodeID!=intent.NodeID||grant.AuthorityEpoch!=intent.AuthorityEpoch||!riskAllows(grant.MaximumRisk,intent.Risk){return a.rejectReceipt(ctx,intent,"GRANT_REJECTED",ErrForbidden)};if err=a.authority.VerifyGrant(ctx,grant);err!=nil{return a.rejectReceipt(ctx,intent,"GRANT_SIGNATURE_INVALID",err)};allowed:=false;for _,selector:=range grant.Selectors{if selectorAllows(selector,intent){allowed=true;break}};if !allowed{return a.rejectReceipt(ctx,intent,"GRANT_SCOPE_REJECTED",ErrForbidden)};if intent.Risk==RiskHigh||intent.Risk==RiskCritical{if intent.Approval==nil{return a.rejectReceipt(ctx,intent,"LOCAL_APPROVAL_REQUIRED",ErrForbidden)};if err=a.authority.VerifyApproval(ctx,intent);err!=nil{return a.rejectReceipt(ctx,intent,"LOCAL_APPROVAL_REJECTED",err)}};payload,err:=a.schemas.Decode(intent.CommandType,intent.SchemaHash,intent.Payload);if err!=nil{return a.rejectReceipt(ctx,intent,"PAYLOAD_INVALID",err)};if err=a.policy.AuthorizeFederated(ctx,intent,grant,payload);err!=nil{return a.rejectReceipt(ctx,intent,"LOCAL_POLICY_REJECTED",err)};receipt,isNew,err:=a.store.AcceptIntent(ctx,intent);if err!=nil{return Receipt{},err};if !isNew{if receipt.Terminal&&len(receipt.Signature)!=0{return receipt,nil};result,observeErr:=a.gateway.ObserveEffect(ctx,intent.EffectID);receipt=receiptFromResult(receipt,result,observeErr,a.clock().UTC());if signErr:=a.sign(ctx,&receipt);signErr!=nil{return receipt,signErr};if err=a.store.CompleteIntent(ctx,receipt);err!=nil&&receipt.Terminal{return receipt,err};return receipt,observeErr};command:=FederatedCommand{IntentID:intent.ID,Origin:OriginFederation,PeerID:intent.PeerID,ActorChain:append([]Actor(nil),intent.ActorChain...),TenantID:intent.TenantID,ResourceKind:intent.ResourceKind,ResourceID:intent.ResourceID,ExpectedGeneration:intent.ExpectedGeneration,IdempotencyKey:intent.IdempotencyKey,EffectID:intent.EffectID,Risk:intent.Risk,Approval:intent.Approval,Payload:payload};result,submitErr:=a.gateway.SubmitFederated(ctx,command);receipt=receiptFromResult(receipt,result,submitErr,a.clock().UTC());if signErr:=a.sign(ctx,&receipt);signErr!=nil{return receipt,signErr};if err=a.store.CompleteIntent(ctx,receipt);err!=nil{return receipt,err};return receipt,submitErr}

func(a *Agent)ReconcilePending(ctx context.Context,limit uint32)([]Receipt,error){intents,err:=a.store.PendingIntents(ctx,limit);if err!=nil{return nil,err};receipts:=make([]Receipt,0,len(intents));for _,intent:=range intents{result,observeErr:=a.gateway.ObserveEffect(ctx,intent.EffectID);receipt:=Receipt{IntentID:intent.ID,NodeID:intent.NodeID,EffectID:intent.EffectID,IdempotencyKey:intent.IdempotencyKey,Status:IntentAmbiguous,LocalGeneration:intent.ExpectedGeneration,UpdatedAt:a.clock().UTC()};receipt=receiptFromResult(receipt,result,observeErr,a.clock().UTC());if err=a.sign(ctx,&receipt);err!=nil{return receipts,err};if err=a.store.CompleteIntent(ctx,receipt);err!=nil&&receipt.Terminal{return receipts,err};receipts=append(receipts,receipt)};return receipts,nil}

func(a *Agent)ApplyRevocation(ctx context.Context,revocation Revocation)error{node,epoch,peer,err:=a.store.State(ctx);if err!=nil{return err};if revocation.NodeID!=node||revocation.PeerID!=peer||revocation.NewAuthorityEpoch<=epoch||revocation.IssuedAt.After(a.clock().UTC().Add(time.Minute)){return ErrStale};registered,err:=a.store.Peer(ctx,peer);if err!=nil{return err};key,ok:=registered.SigningKeys[revocation.SigningKeyID];if !ok{return ErrForbidden};raw:=revocationSigStructure(revocation);if !ed25519.Verify(ed25519.PublicKey(key),raw,revocation.Signature){return ErrForbidden};return a.store.AdvanceAuthority(ctx,epoch,revocation.NewAuthorityEpoch,peer)}
func(a *Agent)LocalRevoke(ctx context.Context,reason string)error{_,epoch,_,err:=a.store.State(ctx);if err!=nil{return err};_ = reason;return a.store.AdvanceAuthority(ctx,epoch,epoch+1,"")}
func(a *Agent)rejectReceipt(ctx context.Context,intent Intent,code string,cause error)(Receipt,error){receipt:=Receipt{IntentID:intent.ID,NodeID:intent.NodeID,EffectID:intent.EffectID,IdempotencyKey:intent.IdempotencyKey,Status:IntentRejected,ErrorCode:code,ErrorMessage:safeError(cause),LocalGeneration:intent.ExpectedGeneration,UpdatedAt:a.clock().UTC(),Terminal:true};_ = a.sign(ctx,&receipt);return receipt,cause}
func(a *Agent)sign(ctx context.Context,receipt *Receipt)error{key,err:=a.signer.ReceiptKeyID(ctx);if err!=nil{return err};receipt.SignatureKeyID=key;signature,err:=a.signer.SignReceipt(ctx,key,receipt.SigStructure());if err!=nil{return err};receipt.Signature=signature;return nil}
func receiptFromResult(receipt Receipt,result LocalResult,err error,now time.Time)Receipt{receipt.OperationID=result.OperationID;receipt.ResultDigest=result.ResultDigest;receipt.ErrorCode=result.ErrorCode;receipt.ErrorMessage=result.ErrorMessage;receipt.LocalGeneration=result.Generation;receipt.UpdatedAt=now;receipt.Terminal=result.Terminal;if result.Status!=""{receipt.Status=result.Status}else if err!=nil{receipt.Status=IntentAmbiguous;receipt.Terminal=false}else{receipt.Status=IntentRunning};if err!=nil&&receipt.ErrorCode==""{receipt.ErrorCode="LOCAL_EFFECT_AMBIGUOUS";receipt.ErrorMessage=safeError(err)};return receipt}
func safeError(err error)string{if err==nil{return ""};message:=err.Error();if len(message)>1024{message=message[:1024]};return message}
func revocationSigStructure(value Revocation)[]byte{copy:=value;copy.Signature=nil;raw,_:=json.Marshal(struct{Domain string `json:"domain"`;Value Revocation `json:"value"`}{"cyberpanel-federation-revocation-v1",copy});return raw}
var _=fmt.Sprintf
var _=errors.Is
